```java
package com.example.visitor.model;

import com.example.visitor.CartItem;
import com.example.visitor.ItemVisitor;

public class PerishableFood implements CartItem {
    private final String name;
    private final double price;
    private final double weightKg;
    private final boolean requiresRefrigeration;

    public PerishableFood(String name, double price, double weightKg, boolean requiresRefrigeration) {
        this.name = name;
        this.price = price;
        this.weightKg = weightKg;
        this.requiresRefrigeration = requiresRefrigeration;
    }

    public String getName() { return name; }
    public double getPrice() { return price; }
    public double getWeightKg() { return weightKg; }
    public boolean requiresRefrigeration() { return requiresRefrigeration; }

    @Override
    public <R> R accept(ItemVisitor<R> visitor) {
        return visitor.visit(this);
    }
}
