### Step 4: Concrete Visitors

Now, we can add behaviors across all products without modifying the classes above.

#### Operation A: Shipping Cost Calculator

```java
package com.example.visitor.operations;

import com.example.visitor.ItemVisitor;
import com.example.visitor.model.Book;
import com.example.visitor.model.Electronics;
import com.example.visitor.model.PerishableFood;

public class ShippingCostCalculator implements ItemVisitor<Double> {
    private static final double BOOK_RATE_PER_KG = 1.50;
    private static final double ELECTRONICS_RATE_PER_KG = 3.20;
    private static final double HAZMAT_SURCHARGE = 12.50;
    private static final double FOOD_RATE_PER_KG = 2.00;
    private static final double REFRIGERATION_SURCHARGE = 8.00;

    @Override
    public Double visit(Book book) {
        return book.getWeightKg() * BOOK_RATE_PER_KG;
    }

    @Override
    public Double visit(Electronics electronics) {
        double cost = electronics.getWeightKg() * ELECTRONICS_RATE_PER_KG;
        if (electronics.containsLithiumBattery()) {
            cost += HAZMAT_SURCHARGE;
        }
        return cost;
    }

    @Override
    public Double visit(PerishableFood food) {
        double cost = food.getWeightKg() * FOOD_RATE_PER_KG;
        if (food.requiresRefrigeration()) {
            cost += REFRIGERATION_SURCHARGE;
        }
        return cost;
    }
}
```

#### Operation B: Invoice Presentation Formatter

```java
package com.example.visitor.operations;

import com.example.visitor.ItemVisitor;
import com.example.visitor.model.Book;
import com.example.visitor.model.Electronics;
import com.example.visitor.model.PerishableFood;

public class InvoiceLineItemVisitor implements ItemVisitor<String> {

    @Override
    public String visit(Book book) {
        return String.format("[BOOK] %-25s | ISBN: %-13s | $%7.2f", 
                book.getTitle(), book.getIsbn(), book.getPrice());
    }

    @Override
    public String visit(Electronics electronics) {
        String hazmatLabel = electronics.containsLithiumBattery() ? " (Hazmat: Li-Ion)" : "";
        return String.format("[ELEC] %-25s | Model: %-12s | $%7.2f%s", 
                electronics.getModel(), electronics.getModel(), electronics.getPrice(), hazmatLabel);
    }

    @Override
    public String visit(PerishableFood food) {
        String coolingLabel = food.requiresRefrigeration() ? " [Cold-Storage]" : "";
        return String.format("[FOOD] %-25s | Unit Price: $%5.2f | $%7.2f%s", 
                food.getName(), food.getPrice(), food.getPrice(), coolingLabel);
    }
}
```

