```java
package com.example.visitor.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Table implements DocumentElement {
    private final List<List<String>> matrix;

    public Table(List<List<String>> matrix) {
        this.matrix = new ArrayList<>();
        for (List<String> row : matrix) {
            this.matrix.add(new ArrayList<>(row));
        }
    }

    public List<List<String>> getMatrix() {
        return Collections.unmodifiableList(matrix);
    }

    @Override
    public void accept(DocumentVisitor visitor) {
        visitor.visit(this); // Resolves statically to visitor.visit(Table)
    }
}
```

### Step 3: Implementing Distinct Algorithmic Visitors

#### Visitor 1: Markdown Rendering Engine

```java
package com.example.visitor.engine;

public class MarkdownExportVisitor implements DocumentVisitor {
    private final StringBuilder output = new StringBuilder();

    @Override
    public void visit(Paragraph paragraph) {
        output.append(paragraph.getContent()).append("\n\n");
    }

    @Override
    public void visit(CodeBlock codeBlock) {
        output.append("```").append(codeBlock.getLanguage()).append("\n")
              .append(codeBlock.getCode()).append("\n")
              .append("```\n\n");
    }

    @Override
    public void visit(Table table) {
        List<List<String>> rows = table.getMatrix();
        if (rows.isEmpty()) return;

        // Render Header
        List<String> header = rows.get(0);
        output.append("| ").append(String.join(" | ", header)).append(" |\n");
        output.append("| ").append(String.join(" | ", Collections.nCopies(header.size(), "---"))).append(" |\n");

        // Render Rows
        for (int i = 1; i < rows.size(); i++) {
            output.append("| ").append(String.join(" | ", rows.get(i))).append(" |\n");
        }
        output.append("\n");
    }

    public String getMarkdown() {
        return output.toString();
    }
}
```

#### Visitor 2: Static Security Scanning Visitor

```java
package com.example.visitor.engine;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Pattern;

public class SecurityAuditVisitor implements DocumentVisitor {
    private static final Pattern SCRIPT_TAG_PATTERN = 
            Pattern.compile(".*<script>.*", Pattern.CASE_INSENSITIVE);

    private final List<String> detectedVulnerabilities = new ArrayList<>();

    @Override
    public void visit(Paragraph paragraph) {
        if (SCRIPT_TAG_PATTERN.matcher(paragraph.getContent()).matches()) {
            detectedVulnerabilities.add("Cross-Site Scripting (XSS) payload detected in Paragraph.");
        }
    }

    @Override
    public void visit(CodeBlock codeBlock) {
        if ("bash".equalsIgnoreCase(codeBlock.getLanguage()) && codeBlock.getCode().contains("rm -rf /")) {
            detectedVulnerabilities.add("Destructive root shell commands detected in CodeBlock.");
        }
    }

    @Override
    public void visit(Table table) {
        for (List<String> row : table.getMatrix()) {
            for (String cell : row) {
                if (SCRIPT_TAG_PATTERN.matcher(cell).matches()) {
                    detectedVulnerabilities.add("XSS Injection payload found in Table cell data: " + cell);
                }
            }
        }
    }

    public List<String> getViolations() {
        return Collections.unmodifiableList(detectedVulnerabilities);
    }

    public boolean isSafe() {
        return detectedVulnerabilities.isEmpty();
    }
}
```

#### Visitor 3: Analytics and Word Count Engine

```java
package com.example.visitor.engine;

import java.util.List;

public class AnalyticsVisitor implements DocumentVisitor {
    private int wordCount = 0;
    private int tableRowCount = 0;
    private int codeBlockCount = 0;

    @Override
    public void visit(Paragraph paragraph) {
        String trimmed = paragraph.getContent().trim();
        if (!trimmed.isEmpty()) {
            wordCount += trimmed.split("\\s+").length;
        }
    }

    @Override
    public void visit(CodeBlock codeBlock) {
        codeBlockCount++;
        String trimmed = codeBlock.getCode().trim();
        if (!trimmed.isEmpty()) {
            wordCount += trimmed.split("\\s+").length;
        }
    }

    @Override
    public void visit(Table table) {
        List<List<String>> rows = table.getMatrix();
        tableRowCount += rows.size();
        for (List<String> row : rows) {
            for (String cell : row) {
                String trimmed = cell.trim();
                if (!trimmed.isEmpty()) {
                    wordCount += trimmed.split("\\s+").length;
                }
            }
        }
    }

    public void printReport() {
        System.out.println("=== Document Analytics ===");
        System.out.println("Total Extracted Words: " + wordCount);
        System.out.println("Total Embedded Tables: " + tableRowCount + " rows");
        System.out.println("Total Code Snippets: " + codeBlockCount);
    }
}
```

